# ---------------------------------------------------------------------------
# fstab — /boot is now the FAT32 ESP (shared between BIOS and UEFI paths).
# ---------------------------------------------------------------------------
FSTAB = """\
# YetiOS fstab — generated by yeti-build.
LABEL=yetios-root  /      ext4   defaults,noatime              0 1
LABEL=YETIOS-ESP   /boot  vfat   defaults,noatime,umask=0077   0 2
proc               /proc  proc   defaults                      0 0
"""